@layer components {
  /* Matches input.css [data-slot="input-group"] 1:1 */
  [data-slot="password-input"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: row;
    align-items: stretch;
    padding-block: 0;
    padding-inline: 0 6px;
    gap: 6px;
    width: 280px;
    max-width: 100%;
    height: 28px;
    border: 0;
    border-radius: 6px;
    outline: 1px solid transparent;
    outline-offset: -1px;
    background: var(--v2-background-bg-base);
    box-shadow: var(--v2-elevation-input);
    flex: none;
    align-self: stretch;
    transition:
      background 85ms ease-out,
      outline-color 85ms ease-out,
      box-shadow 85ms ease-out;
  }

  [data-slot="password-input"][data-appearance="small"] {
    height: 24px;
  }

  [data-slot="password-input"][data-appearance="large"] {
    height: 32px;
  }

  [data-slot="password-input"][data-surface="layer-1"] {
    background: var(--v2-background-bg-layer-01);
  }

  [data-slot="password-input"][data-surface="invisible"] {
    background: transparent;
    box-shadow: none;
  }

  @media (hover: hover) {
    [data-slot="password-input"]:hover:not(
        [data-disabled],
        [data-invalid],
        [data-surface="invisible"]
      ):not(:has([data-slot="password-input-control"]:focus)):not(
        :has([data-invalid])
      ) {
      box-shadow:
        inset 0 0 0 100vmax var(--v2-overlay-simple-overlay-hover),
        var(--v2-elevation-input);
    }

    [data-slot="password-input"][data-surface="invisible"]:hover:not(
        [data-disabled],
        [data-invalid]
      ):not(:has([data-slot="password-input-control"]:focus)):not(
        :has([data-invalid])
      ) {
      background: var(--v2-overlay-simple-overlay-hover);
    }
  }

  [data-slot="password-input"]:has(
      [data-slot="password-input-control"]:focus
    ):not([data-disabled], [data-invalid]):not(:has([data-invalid])) {
    outline-color: var(--v2-border-border-focus);
    box-shadow: none;
  }

  [data-slot="password-input"][data-invalid]:not([data-disabled]),
  [data-slot="password-input"]:has(
      [data-slot="password-input-control"]:is(
          [data-invalid],
          [aria-invalid="true"]
        )
    ):not([data-disabled]) {
    outline-color: var(--v2-state-fg-danger);
    box-shadow: none;
  }

  [data-slot="password-input"][data-disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* ---------------------------------------------------------------- */
  /* Control                                                          */
  /* ---------------------------------------------------------------- */

  [data-slot="password-input-control"] {
    display: block;
    width: 100%;
    min-width: 0;
    flex: 1 1 auto;
    min-height: 0;
    height: 100%;
    padding-block: 0;
    padding-inline: 8px 0;
    margin: 0;
    border: 0;
    background: transparent;
    outline: none;
    font-style: normal;
    font-weight: 440;
    font-size: 13px;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    color: var(--v2-text-text-base);
    font-variation-settings: "slnt" 0;
  }

  [data-slot="password-input"][data-leading-icon]
    [data-slot="password-input-control"] {
    padding-inline-start: 0;
  }

  [data-slot="password-input-control"]::placeholder {
    color: var(--v2-text-text-faint);
    user-select: none;
  }

  [data-slot="password-input"][data-invalid]:not([data-disabled])
    [data-slot="password-input-control"],
  [data-slot="password-input-control"]:is(
      [data-invalid],
      [aria-invalid="true"]
    ):not([data-disabled]) {
    color: var(--v2-state-fg-danger);
    caret-color: var(--v2-state-fg-danger);
  }

  [data-slot="password-input"][data-invalid]:not([data-disabled])
    [data-slot="password-input-control"]::placeholder,
  [data-slot="password-input-control"]:is(
      [data-invalid],
      [aria-invalid="true"]
    ):not([data-disabled])::placeholder {
    color: var(--v2-state-fg-danger);
    opacity: 1;
  }

  /* ---------------------------------------------------------------- */
  /* Leading icon                                                     */
  /* ---------------------------------------------------------------- */

  [data-slot="password-input"] > [data-slot="password-input-leading-icon"] {
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
    padding-inline-start: 8px;
    color: var(--v2-icon-icon-muted);
  }

  [data-slot="password-input"] > [data-slot="password-input-leading-icon"] svg {
    display: block;
    flex: none;
  }

  /* ---------------------------------------------------------------- */
  /* Visibility toggle — matches input-clear                          */
  /* ---------------------------------------------------------------- */

  [data-slot="password-input-toggle"] {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    align-self: center;
    flex: none;
    width: 20px;
    height: 20px;
    padding: 2px;
    border: 0;
    border-radius: 4px;
    background: transparent;
    color: var(--v2-icon-icon-muted);
    cursor: pointer;
    outline: none;
    transition:
      background 85ms ease-out,
      color 85ms ease-out;
  }

  @media (hover: hover) {
    [data-slot="password-input-toggle"]:hover:not(:disabled, [data-disabled]) {
      background-color: var(--v2-overlay-simple-overlay-hover);
      color: var(--v2-text-text-base);
    }
  }

  [data-slot="password-input-toggle"]:active:not(:disabled, [data-disabled]) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="password-input-toggle"]:focus {
    outline: none;
  }

  [data-slot="password-input-toggle"]:focus-visible {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 1px;
  }

  [data-slot="password-input"][data-disabled]
    [data-slot="password-input-toggle"] {
    cursor: not-allowed;
    pointer-events: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="password-input"],
    [data-slot="password-input-toggle"] {
      transition: none;
    }
  }
}
